@app.cell(hide_code=True)
def _(rec):
    # The widgets after the filter are made once per headset. Later cells only set their traits, so each keeps
    # its state and nothing on the page is torn down and rebuilt when a step above it changes. A cell that only
    # writes to a widget takes the bare widget: taking the UI element would rerun it on every click.
    _kw = dict(names=rec["names"], segments=rec["segments"], beeps=rec["beeps"])
    scope_filtered = mo.ui.anywidget(Scope(start=20.0, **_kw))
    scope_ica = mo.ui.anywidget(Scope(start=34.0, **_kw))
    ref_widget = Choice(value=saved(rec, "ref", "device"))
    reference = mo.ui.anywidget(ref_widget)
    ica_widget = Components(pos=rec["pos"].tolist())
    ica_view = mo.ui.anywidget(ica_widget)
    return ica_view, ica_widget, ref_widget, reference, scope_filtered, scope_ica


@app.cell(hide_code=True)
def _(X1, channels, hi, lo, mains, rec, scope_filtered):
    _hum = rec["mains"]
    _ratio = hum_ratio(X1, _hum)
    _p = []
    if lo == 0:
        _p.append("The slow drift is still in.")
    elif lo > 7:
        _p.append(f"A {lo:.0f} Hz high-pass is cutting into alpha.")
    elif lo > 2:
        _p.append(f"A {lo:.1f} Hz high-pass also removes slow brain rhythms (delta, theta).")
    if hi and hi < 14:
        _p.append(f"A {hi:.0f} Hz low-pass is cutting into alpha.")
    if mains and mains != _hum:
        _p.append(f"This recording hums at {_hum} Hz, not {mains}.")
    if _ratio > 3:
        _p.append(f"The {_hum} Hz hum is still {_ratio:.0f}× its neighbouring frequencies.")
    if not _p and (hi is None or hi > 45):
        _p.append("Muscle above 40 Hz is still in.")
    scope_filtered.widget.view = view(X1)
    scope_filtered.widget.bads = list(channels.value["bads"])
    mo.vstack([
        verdict(_p, "Drift, hum and muscle are out; alpha is untouched."),
        scope_filtered,
    ])
    return


