@app.cell(hide_code=True)
def _(X1, channels, names, nch, rec):
    bads = [names.index(b) for b in channels.value["bads"] if b in names]
    can_interpolate = nch >= 8
    X2 = interpolate(X1, rec["pos"], bads) if (bads and can_interpolate) else X1
    save(rec, bads=list(channels.value["bads"]), z_thr=float(channels.value["threshold"]))
    _truth, _mine = TRUE_BADS[rec["id"]], [names[i] for i in bads]
    _p = [f"{b} is broken and still in." for b in _truth if b not in _mine]
    for _b in _mine:
        if _b not in _truth:
            _p.append(f"{_b} is loud from blinks, not broken; ICA can take the blinks out and keep its brain signal."
                      if _b.startswith(("Fp", "AF")) else f"{_b} is fine.")
    if bads and not can_interpolate:
        _p.append(f"With {nch} electrodes there are no neighbours to rebuild {', '.join(_mine)} from, so {'it is' if len(bads) == 1 else 'they are'} dropped.")
    _ok = f"{', '.join(_truth)} was the only broken electrode; it is now rebuilt from its neighbours." if _truth else "Nothing here is broken."
    verdict(_p, _ok) if nch >= 3 else None
    return X2, bads, can_interpolate


@app.cell(hide_code=True)
def _(X2, back, bads, can_interpolate, rec, ref_widget):
    _drop = [] if can_interpolate else bads
    ref_maps, ref_scores = {}, {}
    for _id, _label in reference_options(rec):
        _Y = rereference(X2, _id, rec["names"], _drop)
        ref_maps[_id] = (_label, np.array([alpha_ratio(_Y[i], rec) if i not in _drop else np.nan for i in range(len(_Y))]))
        ref_scores[_id] = score(_Y, rec)
    ref_best = max(ref_scores, key=lambda k: quality(ref_scores[k]))
    _vmax = max(float(np.nanmax(r)) for _, r in ref_maps.values())
    ref_widget.options = [
        {"id": k, "svg": head_svg(rec, 150, values=np.nan_to_num(r, nan=0.0), vmax=_vmax,
         label=f"{lab}: {r[back]:.1f}× at {rec['back']}" if np.isfinite(r[back]) else lab,
         marks=[rec["names"][i] for i in _drop])}
        for k, (lab, r) in ref_maps.items()
    ]
    ref_widget.best = ref_best
    return ref_best, ref_maps, ref_scores


