@app.cell(hide_code=True)
def _(
    X2,
    bads,
    can_interpolate,
    names,
    nch,
    rec,
    ref_best,
    ref_maps,
    ref_scores,
    reference,
):
    ref_mode = reference.value["value"]
    X3 = rereference(X2, ref_mode, rec["names"], [] if can_interpolate else bads)
    save(rec, ref=ref_mode)
    _y, _b = ref_scores[ref_mode], ref_scores[ref_best]
    _p = []
    if quality(_y) < quality(_b) - 0.1:
        _missed = [b for b in TRUE_BADS[rec["id"]] if names.index(b) not in bads]
        if ref_mode == "average" and _missed:
            _p.append(f"An average reference copies {', '.join(_missed)}'s noise into every channel.")
        elif ref_mode == "average" and nch < 8:
            _p.append("With four electrodes the average is half forehead, so it adds blinks to every channel.")
        _p.append(f"{ref_maps[ref_best][0]} gives {_b['alpha']:.1f}× alpha and {_b['eye']:.0f} µV of blink; this gives {_y['alpha']:.1f}× and {_y['eye']:.0f} µV.")
    verdict(_p, f"{_y['alpha']:.1f}× alpha at {rec['back']}, {_y['eye']:.0f} µV of blink at {rec['front']}.") if nch > 1 else None
    return (X3,)


@app.cell(hide_code=True)
def _(X3, bads, can_interpolate, ica_widget, names, nch, rec):
    ica_use = [i for i in range(nch) if can_interpolate or i not in bads]
    if len(ica_use) >= 2:
        S, A, mu = fastica(X3[ica_use])
        ica_eye = eye_correlations(S, X3, names)
        _proxy = eye_proxy(X3, names)
        _open = state_mask(rec, X3.shape[1], "open")
        _t0 = int(np.argmax(np.convolve(np.abs(_proxy) * _open, np.ones(10 * FS), "valid")))
        _f = np.fft.rfftfreq(2 * FS, 1 / FS)
        _band = (_f >= 1) & (_f <= 40)
        _comps = []
        for _k in range(len(S)):
            _w = np.zeros(nch)
            _w[ica_use] = A[:, _k]
            _seg = S[_k, _t0:_t0 + 10 * FS:4]
            _sp = np.mean([np.abs(np.fft.rfft(S[_k, i:i + 2 * FS] * np.hanning(2 * FS))) ** 2 for i in range(0, S.shape[1] - 2 * FS, FS)], 0)
            _comps.append({"w": np.round(_w, 4).tolist(), "snip": np.round(_seg / (np.abs(_seg).max() + 1e-9), 3).tolist(),
                           "spec": np.round(np.log10(_sp[_band] + 1e-12), 3).tolist(), "eye": round(ica_eye[_k], 3)})
        _blinks = [k for k, r in enumerate(ica_eye) if r > 0.5]
        ica_options = {"keep": ([], score(X3, rec)), "blinks": (_blinks, score(unmix(X3, ica_use, S, A, mu, _blinks), rec))}
        ica_best = max(ica_options.values(), key=lambda o: quality(o[1]))[0]
        _key = tuple(round(r, 3) for r in ica_eye)
        _prev = saved(rec, "ica", (None, []))
        ica_widget.comps = _comps
        ica_widget.best = ica_best
        ica_widget.drop = _prev[1] if _prev[0] == _key else []
        ica_key = _key
    else:
        S, A, mu, ica_eye, ica_best, ica_key = None, None, None, [], [], None
        ica_widget.comps = []
    return A, S, ica_best, ica_key, ica_use, mu


@app.cell(hide_code=True)
def _(S, ica_view):
    mo.vstack([
        mo.md("## 5. ICA ( Independent component analisys)"),
        mo.md("ICA is a technique that seperates components of the full signal we see into the features that create it. This helps us to isolate what sources of signal are contributing to the alpha waves we seek to extract, and what may just be blinks. each of these cards represents one of these components, the [[10-20 System]] diagram showing the elctrodes that contribute, and a signal sample of 10s of blinks + spectrum. Try to select/deselect components that help . Below, faint is before and ink is after.")
        if S is not None else mo.md("ICA finds at most as many sources as there are electrodes. With one, blink and brain are the same number; all that is left is throwing time away in step 6."),
        ica_view if S is not None else mo.md(""),
    ])
    return


@app.cell(hide_code=True)
def _(A, S, X3, ica_best, ica_key, ica_use, ica_view, mu, nch, rec, scope_ica):
    ica_drop = [i for i in ica_view.value["drop"] if S is not None and i < len(S)]
    X4 = unmix(X3, ica_use, S, A, mu, ica_drop) if S is not None else X3
    _out = None
    if S is not None:
        save(rec, ica=(ica_key, ica_drop))
        _y, _b, _x3 = score(X4, rec), score(unmix(X3, ica_use, S, A, mu, ica_best), rec), score(X3, rec)
        _p = []
        if quality(_y) < quality(_b) - 0.1:
            _missing = [k + 1 for k in ica_best if k not in ica_drop]
            _extra = [k + 1 for k in ica_drop if k not in ica_best]
            if _missing:
                _p.append(f"Component {', '.join(map(str, _missing))} is the blink and is still in.")
            if _extra and not ica_best:
                _p.append(f"With {nch} channels the blink component also carries alpha: removing it takes alpha from {_x3['alpha']:.1f}× to {_y['alpha']:.1f}×.")
            elif _extra:
                _p.append(f"Component{'s' if len(_extra) > 1 else ''} {', '.join(map(str, _extra))} {'are' if len(_extra) > 1 else 'is'} not blink.")
            _p.append(f"Best here: {_b['alpha']:.1f}× alpha, {_b['eye']:.0f} µV of blink; yours: {_y['alpha']:.1f}×, {_y['eye']:.0f} µV.")
        scope_ica.widget.view = view(X4)
        scope_ica.widget.ghost = view(X3) if ica_drop else {}
        _out = mo.vstack([
            verdict(_p, f"{_y['alpha']:.1f}× alpha, {_y['eye']:.0f} µV of blink."),
            scope_ica,
        ])
    _out
    return (X4,)


