@app.cell(hide_code=True)
def _(X4, bads, can_interpolate, nch, rec, reject):
    reject_use = [i for i in range(nch) if can_interpolate or i not in bads]
    reject_best = best_reject(X4, rec, reject_use)
    reject.widget.ptp = np.round(epoch_ptp(X4[reject_use]).max(0), 1).tolist()
    reject.widget.best = reject_best[1]
    mo.vstack([
        mo.md(r"""
        ## 6. Rejection

        Here we want to try and find the best rejection boundary that cuts off all blink peaks on a given channel, while minimizing the amount of actual signal we are cutting out. If you have done anything with logistic models or F1 score work you would know this as choosing our accuracy/precision tradeoff. Try to drag the line to keep as much of the eyes closed as possible while getting rid of most if not all of the blinks.
        """),
        reject,
    ])
    return reject_best, reject_use


@app.cell(hide_code=True)
def _(X4, rec, reject, reject_best, reject_use):
    _thr = reject.value["threshold"]
    keep = epoch_ptp(X4[reject_use]).max(0) <= (_thr if _thr < NO_REJECT else np.inf)
    save(rec, reject=float(reject.value["threshold"]), pack=pack(rec, X4, keep))
    _ks = kept_share(rec, keep)
    _y = score(X4, rec, keep)
    _qb, _thr, _kb = reject_best
    _b = score(X4, rec, _kb)
    _p = []
    if quality(_y, _ks) < _qb - 0.1:
        _state = min(_ks, key=_ks.get)
        if _ks[_state] < 0.6:
            _p.append(f"Only {_ks[_state]:.0%} of eyes {_state} is left, no longer a fair sample of it.")
        elif np.isfinite(_y["eye"]) and _y["eye"] > 1.5 * _b["eye"]:
            _p.append(f"Blinks still get through: {_y['eye']:.0f} µV at {rec['front']}.")
        _p.append("No rejection does better." if _thr >= NO_REJECT else f"A line at {_thr:.0f} µV does better: {_b['alpha']:.1f}× alpha, {_b['eye']:.0f} µV of blink.")
    verdict(_p, f"{_y['alpha']:.1f}× alpha, {_y['eye']:.0f} µV of blink, {keep.mean():.0%} of the recording kept.")
    return (keep,)


